import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import '../api/api_client.dart'  import '../providers/auth_provider.dart'  import '../widgets/loading_widget.dart'  import '../widgets/empty_state.dart'    class NotificationsScreen extends ConsumerStatefulWidget {    const NotificationsScreen({super.key})      @override    ConsumerState<NotificationsScreen> createState() => _NotificationsScreenState()  }    class _NotificationsScreenState extends ConsumerState<NotificationsScreen> {    List<dynamic> _notifications = []    bool _isLoading = true      @override    void initState() {      super.initState()      _loadNotifications()    }      Future<void> _loadNotifications() async {      try {        final notifications = await ApiClient().getNotifications()        if (mounted) setState(() { _notifications = notifications; _isLoading = false })      } catch (e) {        if (mounted) setState(() => _isLoading = false)      }    }      Future<void> _markRead(int id) async {      try {        await ApiClient().markNotificationRead(id)        _loadNotifications()      } catch (e) {        debugPrint('Mark read error: $e')      }    }      Future<void> _markAllRead() async {      try {        await ApiClient().markAllRead()        _loadNotifications()        ref.read(unreadCountProvider.notifier).state = 0        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            const SnackBar(content: Text('Все уведомления прочитаны')),          )        }      } catch (e) {        debugPrint('Mark all read error: $e')      }    }      IconData _getTypeIcon(String? type) {      switch (type) {        case 'success': return Icons.check_circle_outline        case 'warning': return Icons.warning_amber_outlined        case 'error': return Icons.error_outline        default: return Icons.info_outline      }    }      Color _getTypeColor(String? type) {      switch (type) {        case 'success': return Colors.green        case 'warning': return Colors.orange        case 'error': return Colors.red        default: return Colors.blue      }    }      @override    Widget build(BuildContext context) {      final unreadCount = _notifications.where((n) => n['is_read'] == false).length        return Scaffold(        appBar: AppBar(          title: const Text('Уведомления'),          actions: [            if (unreadCount > 0)              TextButton(                onPressed: _markAllRead,                child: const Text('Прочитать все'),              ),          ],        ),        body: _isLoading            ? const LoadingWidget()            : _notifications.isEmpty                ? const EmptyState(                    icon: Icons.notifications_none,                    title: 'Нет уведомлений',                    subtitle: 'Здесь появятся ваши уведомления',                  )                : RefreshIndicator(                    onRefresh: _loadNotifications,                    child: ListView.builder(                      padding: const EdgeInsets.all(16),                      itemCount: _notifications.length,                      itemBuilder: (context, index) {                        final notif = _notifications[index]                        final isRead = notif['is_read'] == true                          return Dismissible(                          key: Key(notif['id'].toString()),                          direction: DismissDirection.endToStart,                          background: Container(                            alignment: Alignment.centerRight,                            padding: const EdgeInsets.only(right: 20),                            decoration: BoxDecoration(                              color: Colors.green,                              borderRadius: BorderRadius.circular(12),                            ),                            child: const Icon(Icons.check, color: Colors.white),                          ),                          onDismissed: (_) => _markRead(notif['id']),                          child: Card(                            margin: const EdgeInsets.only(bottom: 8),                            color: isRead ? null : Theme.of(context).colorScheme.primary.withOpacity(0.05),                            child: ListTile(                              leading: Container(                                padding: const EdgeInsets.all(8),                                decoration: BoxDecoration(                                  color: _getTypeColor(notif['notification_type']).withOpacity(0.1),                                  shape: BoxShape.circle,                                ),                                child: Icon(                                  _getTypeIcon(notif['notification_type']),                                  color: _getTypeColor(notif['notification_type']),                                  size: 20,                                ),                              ),                              title: Text(                                notif['title'] ?? 'Без заголовка',                                style: TextStyle(                                  fontWeight: isRead ? FontWeight.normal : FontWeight.w600,                                ),                              ),                              subtitle: Column(                                crossAxisAlignment: CrossAxisAlignment.start,                                children: [                                  Text(                                    notif['body'] ?? '',                                    style: TextStyle(fontSize: 13, color: Colors.grey[600]),                                    maxLines: 2,                                    overflow: TextOverflow.ellipsis,                                  ),                                  const SizedBox(height: 4),                                  Text(                                    notif['created_at'] != null                                        ? '${DateTime.parse(notif['created_at']).day.toString().padLeft(2, '0')}.${DateTime.parse(notif['created_at']).month.toString().padLeft(2, '0')} ${DateTime.parse(notif['created_at']).hour.toString().padLeft(2, '0')}:${DateTime.parse(notif['created_at']).minute.toString().padLeft(2, '0')}'                                        : '',                                    style: TextStyle(fontSize: 11, color: Colors.grey[400]),                                  ),                                ],                              ),                              trailing: !isRead                                  ? Container(                                      width: 8,                                      height: 8,                                      decoration: BoxDecoration(                                        color: Theme.of(context).colorScheme.primary,                                        shape: BoxShape.circle,                                      ),                                    )                                  : null,                              onTap: () {                                if (!isRead) _markRead(notif['id'])                              },                            ),                          ),                        )                      },                    ),                  ),      )    }  }